package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.List;
import java.util.ArrayList;

/** Invented rows only. No native observation, account state or action authority. */
public class NativeProgressLayoutDiagnosticsTest {
    private static FrameStructureEvidence.Line row(String text,int y,double score){return new FrameStructureEvidence.Line(text,10,y,350,20,score);}
    private static NativeProgressLayoutDiagnostics observe(FrameStructureEvidence.Line... rows){Object o=new Object();var b=new FrameStructureEvidence.Binding(o,o,o,o);return NativeProgressLayoutDiagnostics.observe(b,b,List.of(rows),500,1000);}
    @Test public void sourceAliasesAreEnumsOnly(){String s=observe(row("Search to earn",20,.99999),row("阅读以赚取",60,.9)).summary(true);assertTrue(s.contains("role=EXACT_REWARD_SEARCH_TITLE origin=SOURCE_BACKED alias=SEARCH_TO_EARN"));assertTrue(s.contains("role=EXACT_REWARD_READ_TITLE origin=SOURCE_BACKED alias=READ_EARN_ZH"));assertTrue(s.contains("score=1.0000"));assertFalse(s.contains("Search to earn"));assertFalse(s.contains("阅读以赚取"));}
    @Test public void allSourceBackedAliasesAreAccepted(){String[] labels={"search to earn","搜索以赚取","search points","搜索积分","read to earn","阅读以赚取"};for(String label:labels)assertTrue(label,observe(row(label,20,.99)).summary(true).contains("origin=SOURCE_BACKED"));}
    @Test public void wholeHypothesisAliasIsSeparatedFromEvidence(){String s=observe(row("Search and earn",20,.99),row("通过搜索赚取积分",50,.99)).summary(true);assertTrue(s.contains("origin=HYPOTHESIS_ONLY alias=SEARCH_AND_EARN"));assertTrue(s.contains("origin=HYPOTHESIS_ONLY alias=SEARCH_VIA_POINTS_HYP_ZH"));assertTrue(s.contains("counterAuthority=false actionAuthority=false"));assertFalse(s.contains("=KNOWN"));}
    @Test public void hypothesisPrefixDoesNotMatchLongerField(){String s=observe(row("Search and earn SECRET private details",20,.99)).summary(true);assertFalse(s.contains("HYPOTHESIS_ONLY"));assertTrue(s.contains("GENERIC_SEARCH_TOKEN"));assertFalse(s.contains("SECRET"));assertFalse(s.contains("private details"));}
    @Test public void sameRowCounterIsFormatOnlyAndDoesNotExportNumbers(){String s=observe(row("search points 59/60",20,.99)).summary(true);assertTrue(s.contains("role=STRICT_SAME_ROW_COUNTER"));assertFalse(s.contains("59/60"));assertFalse(s.contains(" n="));assertFalse(s.contains("=KNOWN"));}
    @Test public void splitTitleFractionNeverAssociated(){String s=observe(row("search to earn",20,.99),row("9 / 30",50,.99)).summary(true);assertTrue(s.contains("EXACT_REWARD_SEARCH_TITLE"));assertTrue(s.contains("role=BARE_FRACTION"));assertTrue(s.contains("n=9 d=30 fractionRole=UNATTRIBUTED"));assertTrue(s.contains("association=NONE"));assertFalse(s.contains("STRICT_SAME_ROW_COUNTER"));}
    @Test public void fractionsCannotBecomeCompletedTask(){String s=observe(row("30/30",20,.99)).summary(true);assertTrue(s.contains("fractionRole=UNATTRIBUTED"));assertFalse(s.contains("Complete=true"));assertFalse(s.contains("READING=KNOWN"));}
    @Test public void bareFractionBoundsAndMalformedValues(){for(String value:new String[]{"-1/30","1/0","10001/10001","999999999/30","1.5/30","1/2/3"}){String s=observe(row(value,20,.99)).summary(true);assertTrue(value,s.contains("MALFORMED_FRACTION"));assertFalse(value,s.contains(" n="));}assertTrue(observe(row("10000/10000",20,.99)).summary(true).contains("n=10000 d=10000"));}
    @Test public void unrelatedLowConfidenceRowRetainsDiagnosticOnly(){String s=observe(row("search to earn",20,.4),row("NOT_FOR_EXPORT",50,.3)).summary(true);assertTrue(s.contains("lowConfidenceRows=2"));assertTrue(s.contains("low=true"));assertTrue(s.contains("row=0"));assertFalse(s.contains("row=1"));assertFalse(s.contains("NOT_FOR_EXPORT"));assertFalse(s.contains("=KNOWN"));}
    @Test public void completeBatchShapeValidationPrecedesAnyEntry(){String s=observe(row("search to earn",20,.99),row("secret",-1,.99)).summary(true);assertTrue(s.contains("rowQuality=BOX"));assertTrue(s.contains("layoutEvidence=UNQUALIFIED"));assertFalse(s.contains("row=0"));assertFalse(s.contains("alias=SEARCH_TO_EARN"));}
    @Test public void bindingMismatchSuppressesCandidates(){Object a=new Object(),b=new Object();String s=NativeProgressLayoutDiagnostics.observe(new FrameStructureEvidence.Binding(a,a,a,a),new FrameStructureEvidence.Binding(b,b,b,b),List.of(row("123/456",20,.99)),500,1000).summary(true);assertTrue(s.contains("rowQuality=BINDING"));assertFalse(s.contains("n=123"));assertFalse(s.contains("box="));}
    @Test public void finalUnqualifiedSuppressesEveryCandidateNumberAndAlias(){String s=observe(row("123/456",327,.87654),row("Search to earn",400,.99)).summary(false);assertTrue(s.contains("layoutEvidence=UNQUALIFIED"));for(String value:new String[]{"row=","box=","score=","n=123","d=456","alias=","123","327"})assertFalse(value,s.contains(value));}
    @Test public void originalNativeIndicesAndOrderRemain(){String s=observe(row("ignored",20,.99),row("read",700,.99),row("search",100,.99)).summary(true);assertFalse(s.contains("row=0"));assertTrue(s.indexOf("row=1")<s.indexOf("row=2"));assertTrue(s.contains("box=10,700,350,20"));assertTrue(s.contains("box=10,100,350,20"));assertFalse(s.contains("toolbar"));}
    @Test public void reportIsCappedAndExplicitlyTruncated(){var list=new ArrayList<FrameStructureEvidence.Line>();for(int i=0;i<128;i++)list.add(row("Search to earn 1/2",20,.9));Object o=new Object();var b=new FrameStructureEvidence.Binding(o,o,o,o);String s=NativeProgressLayoutDiagnostics.observe(b,b,list,500,1000).summary(true);assertTrue(s.contains("candidateTotal=128 emitted=24 truncated=true"));assertTrue(s.contains("row=23 "));assertFalse(s.contains("row=24 "));assertTrue(s.length()<6000);}
    @Test public void englishHistoricalFieldIsStrictAndDiagnosticOnly(){String s=observe(row("Search to earn, , 17 out of 61 points earned",20,.99),row("Read to earn, , 18 out of 31 points earned",50,.99)).summary(true);assertTrue(s.contains("HISTORICAL_SUMMARY_FORMAT_MATCH"));assertTrue(s.contains("origin=HISTORICAL_SOURCE alias=SEARCH_TO_EARN"));assertTrue(s.contains("origin=HISTORICAL_SOURCE alias=READ_TO_EARN"));assertFalse(s.contains("17 out of"));assertFalse(s.contains(" n="));assertFalse(s.contains("=KNOWN"));}
    @Test public void chineseHistoricalFieldIsStrict(){String s=observe(row("搜索以赚取, , 已赚取 17 积分(需要 61 积分)",20,.99),row("阅读以赚取, , 已赚取 18 积分(需要 31 积分)",50,.99)).summary(true);assertTrue(s.contains("origin=HISTORICAL_SOURCE alias=SEARCH_EARN_ZH"));assertTrue(s.contains("origin=HISTORICAL_SOURCE alias=READ_EARN_ZH"));assertFalse(s.contains("已赚取"));String malformed=observe(row("search to earn 17 out of 61 points earned",20,.99)).summary(true);assertFalse(malformed.contains("HISTORICAL_SUMMARY_FORMAT_MATCH"));}
    @Test public void genericAndContainingCluesHaveNoRawField(){String s=observe(row("Search secrets",20,.99),row("Read secrets",50,.99),row("research secrets",80,.99),row("already secrets",110,.99),row("搜索秘密",140,.99),row("阅读秘密",170,.99)).summary(true);assertTrue(s.contains("GENERIC_SEARCH_TOKEN"));assertTrue(s.contains("GENERIC_READ_TOKEN"));assertTrue(s.contains("OTHER_SEARCH_CONTAINING"));assertTrue(s.contains("OTHER_READ_CONTAINING"));assertFalse(s.contains("secrets"));assertFalse(s.contains("秘密"));}
    @Test public void inputMutationCannotChangeImmutableProjection(){var rows=new ArrayList<FrameStructureEvidence.Line>();rows.add(row("1/2",20,.99));Object o=new Object();var b=new FrameStructureEvidence.Binding(o,o,o,o);var value=NativeProgressLayoutDiagnostics.observe(b,b,rows,500,1000);String before=value.summary(true);rows.clear();assertEquals(before,value.summary(true));}
    @Test public void sameRowFormatUsesCoreIntegerBoundsWithoutExportingValues(){assertTrue(observe(row("search points 10001/20000",20,.99)).summary(true).contains("STRICT_SAME_ROW_COUNTER"));assertFalse(observe(row("search points 2147483648/2147483648",20,.99)).summary(true).contains("STRICT_SAME_ROW_COUNTER"));assertFalse(observe(row("search points 61/60",20,.99)).summary(true).contains("STRICT_SAME_ROW_COUNTER"));}
    @Test public void bareDateLikeFractionIsStillUnattributedNotTaskRejected(){String s=observe(row("12/11",20,.99)).summary(true);assertTrue(s.contains("n=12 d=11 fractionRole=UNATTRIBUTED"));assertFalse(s.contains("STRICT_SAME_ROW_COUNTER"));}
    @Test public void historicalGrammarDoesNotNormalizeDifferentOriginalFields(){for(String text:new String[]{"搜索以赚取, , 已赚取17积分(需要61积分)","search to earn, , 17 out of 61 points earned","Search  to earn, , 17 out of 61 points earned","搜索以赚取, , 已赚取 17 积分（需要 61 积分）"})assertFalse(text,observe(row(text,20,.99)).summary(true).contains("HISTORICAL_SUMMARY_FORMAT_MATCH"));}
    @Test public void strictSameRowIsExplicitlyFormatOnlyEvenForLowConfidenceBatch(){String s=observe(row("search points 17/61",20,.4),row("private",50,.3)).summary(true);assertTrue(s.contains("role=STRICT_SAME_ROW_COUNTER"));assertTrue(s.contains("formatOnly=true"));assertTrue(s.contains("low=true"));assertTrue(s.contains("counterAuthority=false"));assertFalse(s.contains("=KNOWN"));}
    @Test public void locateStopUsesAllOriginalRowsBeyondPresentationCap(){var rows=new ArrayList<FrameStructureEvidence.Line>();for(int i=0;i<24;i++)rows.add(row("search unrelated",20,.99));rows.add(row("read to earn",50,.4));Object o=new Object();var b=new FrameStructureEvidence.Binding(o,o,o,o);var value=NativeProgressLayoutDiagnostics.observe(b,b,rows,500,1000);assertTrue(value.locateRowsUsable());assertTrue(value.locateStopClue());String s=value.summary(true);assertTrue(s.contains("candidateTotal=25 emitted=24 truncated=true"));assertFalse(s.contains("EXACT_REWARD_READ_TITLE"));assertFalse(s.contains("row=24 "));}
    @Test public void genericOtherAndFractionRowsDoNotStopLocating(){for(String text:new String[]{"Search","Read","research","already","搜索别的内容","阅读别的内容","1/2","-1/2","10001/10001"}){var value=observe(row(text,20,.99));assertTrue(text,value.locateRowsUsable());assertFalse(text,value.locateStopClue());}}
    @Test public void eachExactRoleStopsEvenLowConfidenceWithoutCounterAuthority(){for(String text:new String[]{"search to earn","read to earn","search points 17/61","Search to earn, , 17 out of 61 points earned","搜索以赚取, , 已赚取 17 积分(需要 61 积分)","Search and earn","阅读赚积分"}){var value=observe(row(text,20,.1));assertTrue(text,value.locateRowsUsable());assertTrue(text,value.locateStopClue());String s=value.summary(true);assertTrue(s.contains("counterAuthority=false actionAuthority=false"));assertFalse(s.contains("=KNOWN"));}}
    @Test public void invalidWholeBatchCannotSupplyLocateClue(){var value=observe(row("read to earn",20,.99),row("bad box",-1,.99));assertFalse(value.locateRowsUsable());assertFalse(value.locateStopClue());}
    @Test public void emptyAndWhitespaceOnlyRowsAreNotLocateUsable(){assertFalse(observe().locateRowsUsable());var value=observe(row("   ",20,.99));assertFalse(value.locateRowsUsable());assertFalse(value.locateStopClue());}
    @Test public void locateQueriesDoNotChangeV41Serialization(){var value=observe(row("read to earn",20,.4));String before=value.summary(true),unqualified=value.summary(false);assertTrue(value.locateRowsUsable());assertTrue(value.locateStopClue());assertEquals(before,value.summary(true));assertEquals(unqualified,value.summary(false));assertFalse(before.contains("locate"));}
    @Test public void locateClassificationDoesNotWidenHypothesesOrHistoricalGrammar(){for(String text:new String[]{"Search and earn extra","搜索以赚取, , 已赚取17积分(需要61积分)","search to earn, , 17 out of 61 points earned"})assertFalse(text,observe(row(text,20,.99)).locateStopClue());}
    @Test public void loginAndSourceBackedErrorHeuristicsStopEvenLowConfidence(){for(String text:new String[]{"Please sign in now","LOG IN","Login required","请登录","请登入","出现问题，请稍后","尝试刷新页面","image load error"}){var value=observe(row(text,20,.1));assertTrue(text,value.locateRowsUsable());assertTrue(text,value.locateSafetyStop());assertFalse(text,value.locateStopClue());assertFalse(value.summary(true).contains(text));}}
    @Test public void safetyVetoSeesNoncandidateRowsBeyondEmissionCap(){var rows=new ArrayList<FrameStructureEvidence.Line>();for(int i=0;i<24;i++)rows.add(row("Search other",20,.99));rows.add(row("sign in",50,.2));Object o=new Object();var b=new FrameStructureEvidence.Binding(o,o,o,o);var value=NativeProgressLayoutDiagnostics.observe(b,b,rows,500,1000);assertTrue(value.locateSafetyStop());assertFalse(value.locateStopClue());assertFalse(value.summary(true).contains("sign in"));}
    @Test public void safetyHeuristicUsesWholeWordsAndExactErrorRule(){for(String text:new String[]{"design interior","catalog index","logins","image load error extra","ordinary unrelated"})assertFalse(text,observe(row(text,20,.99)).locateSafetyStop());}
    @Test public void safetyAccessorCannotChangeV41Serialization(){var value=observe(row("sign in",20,.1));String before=value.summary(true);assertTrue(value.locateSafetyStop());assertEquals(before,value.summary(true));assertFalse(before.contains("locateSafety"));assertFalse(observe(row("sign in",-1,.1)).locateSafetyStop());}
}
